    cleaned = " ".join(str(name or "").split())
    cleaned = cleaned.strip()
    safe = "".join(
        ch if ch.isalnum() or ch in {"_", "-"} else "_" for ch in cleaned
    )
    safe = safe.strip("_")
    if not safe:
        safe = "subroutine"
    return safe.lower()

